.progress-container {
  width: 90%;
  max-width: 400px;
  margin: 20px auto;
  padding: 16px;
  border-radius: 16px;
  background: transparent;
  position: relative;
}

.progress-grid {
  display: grid;
  grid-template-columns: repeat(25, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 4px;
  perspective: 1200px;
}

.pixel {
  position: relative;
  width: 100%;
  padding-top: 100%;
  border-radius: 50%;
  transform-style: preserve-3d;
  transform-origin: center;
  background: #111;
  box-shadow:
    0 0 2px #4caf50,
    0 0 5px #4caf50,
    0 0 10px #4caf50;
  animation-name: fill-animation;
  animation-duration: 10s;
  animation-timing-function: linear;
  animation-iteration-count: 2;
  animation-fill-mode: forwards;
  opacity: 0;
  transform: translateZ(0);
  will-change: transform, opacity;
}

@keyframes fill-animation {
  0%,
  1% {
    opacity: 0;
    transform: rotateY(180deg) scale(0.8);
    background: #111;
    box-shadow:
      0 0 2px #000,
      0 0 5px #000,
      0 0 10px #000;
  }
  10% {
    opacity: 1;
    transform: rotateY(90deg) scale(1);
    background: #4caf50;
    box-shadow:
      0 0 5px #4caf50,
      0 0 15px #4caf50,
      0 0 30px #4caf50;
  }
  50% {
    transform: rotateY(0deg) scale(1.2);
    background: #4caf50;
    box-shadow:
      0 0 12px #4caf50,
      0 0 24px #4caf50,
      0 0 40px #4caf50;
  }
  99% {
    transform: rotateY(0deg) scale(1.1);
    background: #fdd835;
    box-shadow:
      0 0 8px #fdd835,
      0 0 25px #fdd835,
      0 0 60px #fdd835;
    opacity: 1;
  }
  100% {
    background: #ff2f92;
    box-shadow:
      0 0 15px #ff2f92,
      0 0 40px #ff2f92,
      0 0 80px #ff2f92;
    transform: rotateY(720deg) scale(1.5);
    opacity: 1;
  }
}

.pixel::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 150%;
  height: 150%;
  background: radial-gradient(
    circle at 50% 50%,
    rgba(255, 255, 255, 0.4) 0%,
    rgba(255, 255, 255, 0) 60%
  );
  transform: translate(-50%, -50%) rotate(45deg);
  mix-blend-mode: color-dodge;
  opacity: 0;
  transition: opacity 0.6s ease-in;
}

.pixel:hover::after,
.pixel:hover {
  opacity: 1;
}

